const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geom = ee.Geometry.Polygon(
    [[[101.5, 27.5],
      [101.5, 33.5],
      [108.5, 33.5],
      [108.5, 27.5]]], null, false); // Approximate bounding box for Sichuan Basin

  const startYear1 = '2006-01-01';
  const endYear1 = '2006-12-31';
  const startYear2 = '2020-01-01';
  const endYear2 = '2020-12-31';

  const AOD_BAND = 'Optical_Depth_055_Deep_Blue_h550_h047_h067';
  const QA_BAND = 'AOD_550_Dark_Target_Deep_Blue_QA_Flag';
  const SCALE_FACTOR = 0.001;

  // Function to mask invalid AOD values and apply scale factor
  function maskAndScaleAOD(image) {
    const qa = image.select(QA_BAND);
    // Keep pixels with QA flags 0 (best) or 1 (good)
    const validQaMask = qa.lte(1);
    const aod = image.select(AOD_BAND).multiply(SCALE_FACTOR);
    // Mask out values where QA is not good, or AOD is outside reasonable range (0 to 2 for AOD is generally acceptable)
    const validAodMask = aod.gte(0).and(aod.lte(2)); // AOD usually between 0 and 2.
    return aod.updateMask(validQaMask.and(validAodMask));
  }

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES');

  const col1 = collection.filterDate(startYear1, endYear1).filterBounds(geom);
  const col2 = collection.filterDate(startYear2, endYear2).filterBounds(geom);

  let col1Size = await col1.size().getInfo();
  let col2Size = await col2.size().getInfo();

  if (col1Size === 0 || col2Size === 0) {
    console.log(`2006 Images: ${col1Size}`);
    console.log(`2020 Images: ${col2Size}`);
    console.log("Not enough images found for one or both periods.");
    console.log("C1");
    return;
  }

  // Apply masking and scaling
  const processedCol1 = col1.map(maskAndScaleAOD);
  const processedCol2 = col2.map(maskAndScaleAOD);

  // Take the mean composite for each year
  const meanImage1 = processedCol1.mean();
  const meanImage2 = processedCol2.mean();

  // Define a reducer and scale
  const reducer = ee.Reducer.mean();
  const scale = 1000; // MODIS resolution is 1km, so 1000m scale is appropriate

  // Calculate pixel count for validation (C2 check)
  const countPixels1 = await meanImage1.select(AOD_BAND).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9
  }).get(AOD_BAND).getInfo();

  const countPixels2 = await meanImage2.select(AOD_BAND).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: 1e9
  }).get(AOD_BAND).getInfo();

  if (countPixels1 === 0 || countPixels2 === 0) {
    console.log(`2006 Valid Pixels: ${countPixels1}`);
    console.log(`2020 Valid Pixels: ${countPixels2}`);
    console.log("No valid pixels remain after masking for one or both periods.");
    console.log("C2");
    return;
  }

  // 4. Calculation
  const meanAOD1 = await meanImage1.reduceRegion({
    reducer: reducer,
    geometry: geom,
    scale: scale,
    maxPixels: 1e9
  }).get(AOD_BAND).getInfo();

  const meanAOD2 = await meanImage2.reduceRegion({
    reducer: reducer,
    geometry: geom,
    scale: scale,
    maxPixels: 1e9
  }).get(AOD_BAND).getInfo();

  // 5. Validation & Final Answer
  if (meanAOD1 === null || meanAOD2 === null || isNaN(meanAOD1) || isNaN(meanAOD2)) {
    console.log(`2006 Mean AOD: ${meanAOD1}`);
    console.log(`2020 Mean AOD: ${meanAOD2}`);
    console.log("Calculation resulted in Null/NaN.");
    console.log("C3");
    return;
  }

  console.log(`2006 Images: ${col1Size}`);
  console.log(`2020 Images: ${col2Size}`);
  console.log(`2006 Valid Pixels: ${countPixels1}`);
  console.log(`2020 Valid Pixels: ${countPixels2}`);
  console.log(`Mean AOD 2006: ${meanAOD1.toFixed(3)}`);
  console.log(`Mean AOD 2020: ${meanAOD2.toFixed(3)}`);

  if (meanAOD2 < meanAOD1) {
    console.log("A"); // Yes, AOD decreased
  } else {
    console.log("B"); // No, AOD did not decrease or increased
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
